<script setup lang="ts">
import type { JobSnapshot, WorkspaceDetail } from '../../../../types/api'
definePageMeta({ middleware: 'workspace' })
const route = useRoute(); const api = useApi(); const activity = useActivityStore(); const workspace = ref<WorkspaceDetail>(); const wizard = ref(false); const busy = ref(false); const error = ref('')
const id = computed(() => String(route.params.workspaceId))
onMounted(load)
async function load() { try { workspace.value = await api.get(`/workspaces/${encodeURIComponent(id.value)}`) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not inspect sites.' } }
async function createSite(value: { name: string; modules: string[]; branch: string; force: boolean }) { busy.value = true; try { const job = await api.post<JobSnapshot>(`/workspaces/${encodeURIComponent(id.value)}/sites`, value); activity.trackJob(job); wizard.value = false; await navigateTo('/activity') } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not create site.' } finally { busy.value = false } }
</script>
<template><section class="page-sheet"><header class="page-header"><div><p class="eyebrow">Workspace inventory</p><h1>Sites</h1><p>Applications inspected from this workspace’s explicit <code>apps/</code> directory.</p></div><button class="compact-button compact-button--primary" type="button" @click="wizard = true">Create site</button></header><p v-if="error" class="notice notice--error">{{ error }}</p><div v-if="workspace?.sites.length" class="card-grid"><NuxtLink v-for="site in workspace.sites" :key="site.id" class="site-card" :to="`/workspaces/${id}/sites/${site.id}`"><p class="eyebrow">{{ site.packageManager || 'Package manager unknown' }}</p><h2>{{ site.name }}</h2><code>{{ site.root }}</code><div class="chip-row"><span v-for="module in site.modules" :key="module">{{ module }}</span></div><small>{{ site.dependenciesInstalled ? 'Dependencies installed' : 'Install required' }} →</small></NuxtLink></div><div v-else class="empty-state"><h2>No sites inspected.</h2><p>Create one through a reviewed provisioning job.</p></div></section><SiteWizard :open="wizard" :busy="busy" @close="wizard = false" @submit="createSite" /></template>
